tasks.curl:
curl -X POST http://localhost:8092/v1/audio/speech \
  -H "Content-Type: application/json" \
  -d '{
    "model": "IndexTeam/IndexTTS-2.5",
    "input": "你好，这是 IndexTTS-2.5 语音合成测试。",
    "voice": "demo_voice",
    "speed": 1.0,
    "response_format": "wav",
    "extra_params": {
      "lang": "zh",
      "text_normalization": true
    }
  }' --output output.wav
